with valid as (select id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, pressure * temp_c as pressure_times_temp_c, case when humidity >= 79 then 'High' when humidity >= 28 then 'Medium' else 'Low' end as humidity_level from device_readings where temp_c <= 24), gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '30' minute then 1 else 0 end as session_start_flag from valid), sessions_device_readings as (select *, sum(session_start_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from gaps), with_gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval 45 minutes then 1 else 0 end as new_group_flag from sessions_device_readings), islands as (select id, device_code, reading_ts, temp_c, pressure_times_temp_c, humidity_level, island_id, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id_2 from with_gaps), with_gaps_2 as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '45' minute then 1 else 0 end as new_group_flag from islands), islands_device_readings as (select *, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id_3 from with_gaps_2), ranked as (select * from islands_device_readings qualify rank() over (partition by device_code order by new_group_flag desc) = 1), kept_keys as (select id from ranked intersect select id from device_readings where device_code in ('DV-03', 'DV-04', 'DV-01')), kept_rows as (select s.* from ranked s inner join kept_keys k on s.id = k.id) select id, reading_ts, temp_c, pressure_times_temp_c, humidity_level, island_id, island_id_3 from kept_rows order by reading_ts desc
